#include "virtual_broadcast/broadcaster/si.hpp"
#include <algorithm>
#include <stdexcept>

namespace vb {
std::vector<std::uint8_t>DescriptorWriter::Service(std::uint8_t type,std::span<const std::uint8_t>provider,std::span<const std::uint8_t>name){if(provider.size()>255||name.size()>255||3+provider.size()+name.size()>255)throw std::length_error("service_descriptor too long");std::vector<std::uint8_t>b{kDescriptorService,static_cast<std::uint8_t>(3+provider.size()+name.size()),type,static_cast<std::uint8_t>(provider.size())};b.insert(b.end(),provider.begin(),provider.end());b.push_back(static_cast<std::uint8_t>(name.size()));b.insert(b.end(),name.begin(),name.end());return b;}
std::vector<std::uint8_t>DescriptorWriter::NetworkName(std::span<const std::uint8_t>name){if(name.size()>255)throw std::length_error("network_name_descriptor too long");std::vector<std::uint8_t>b{kDescriptorNetworkName,static_cast<std::uint8_t>(name.size())};b.insert(b.end(),name.begin(),name.end());return b;}
std::vector<std::uint8_t>DescriptorWriter::ServiceList(std::uint16_t sid,std::uint8_t type){return{kDescriptorServiceList,3,static_cast<std::uint8_t>(sid>>8),static_cast<std::uint8_t>(sid),type};}
std::vector<std::uint8_t>DescriptorWriter::TsInformation(std::uint8_t key,std::span<const std::uint8_t>name){if(key<1||key>12)throw std::invalid_argument("remote_control_key_id must be 1..12");if(name.size()>63)throw std::length_error("TS name exceeds 6-bit length");std::vector<std::uint8_t>b{kDescriptorTsInformation,static_cast<std::uint8_t>(2+name.size()),key,static_cast<std::uint8_t>(name.size()<<2)};b.insert(b.end(),name.begin(),name.end());return b;}
std::vector<std::uint8_t>DescriptorWriter::LocalTimeOffset(const std::string&country,int offset,std::chrono::sys_seconds change){if(country.size()!=3||std::any_of(country.begin(),country.end(),[](char c){return c<'A'||c>'Z';}))throw std::invalid_argument("country_code");if(std::abs(offset)>13*60)throw std::out_of_range("local offset");const auto off=BcdEncoder::EncodeHoursMinutes(offset);const auto when=MjdTimeEncoder::EncodeJst(change);std::vector<std::uint8_t>b{kDescriptorLocalTimeOffset,13,static_cast<std::uint8_t>(country[0]),static_cast<std::uint8_t>(country[1]),static_cast<std::uint8_t>(country[2]),static_cast<std::uint8_t>(0x02|(offset<0?1:0)),off[0],off[1]};b.insert(b.end(),when.begin(),when.end());b.push_back(off[0]);b.push_back(off[1]);return b;}
}
